const saRaw = $input.first().json.sa_json;
const audience = String($input.first().json.token_audience || "").trim();
const endpoint = String($input.first().json.token_endpoint || "").trim();

if (!saRaw) throw new Error("Missing input field: sa_json (service account JSON string)");
if (!audience) throw new Error("Missing input field: token_audience");
if (!endpoint) throw new Error("Missing input field: token_endpoint");

let sa;
try {
  sa = typeof saRaw === "string" ? JSON.parse(saRaw) : saRaw;
} catch (e) {
  throw new Error("sa_json is not valid JSON");
}

if (!sa.client_email || !sa.private_key) {
  throw new Error("sa_json must include client_email and private_key");
}

const now = Math.floor(Date.now() / 1000);

const header = { alg: "RS256", typ: "JWT" };
const claimSet = {
  iss: sa.client_email,
  scope: "https://www.googleapis.com/auth/cloud-platform",
  aud: "https://oauth2.googleapis.com/token",
  iat: now,
  exp: now + 3600,
};

const b64url = (obj) =>
  Buffer.from(JSON.stringify(obj))
    .toString("base64")
    .replace(/=/g, "")
    .replace(/\+/g, "-")
    .replace(/\//g, "_");

const unsigned = `${b64url(header)}.${b64url(claimSet)}`;

const crypto = require("crypto");
const signer = crypto.createSign("RSA-SHA256");
signer.update(unsigned);
signer.end();

const sig = signer
  .sign(sa.private_key, "base64")
  .replace(/=/g, "")
  .replace(/\+/g, "-")
  .replace(/\//g, "_");

const jwt = `${unsigned}.${sig}`;

const formEncode = (obj) =>
  Object.entries(obj)
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`)
    .join("&");

const tokenRes = await this.helpers.httpRequest({
  method: "POST",
  url: "https://oauth2.googleapis.com/token",
  headers: { "Content-Type": "application/x-www-form-urlencoded" },
  body: formEncode({
    grant_type: "urn:ietf:params:oauth:grant-type:jwt-bearer",
    assertion: jwt,
  }),
});

if (!tokenRes?.access_token) {
  throw new Error("Failed to mint Google access token. Check service account JSON and permissions.");
}

return [
  {
    json: {
      gcp_access_token: tokenRes.access_token,
      sa_email: sa.client_email,
      audience,
      endpoint,
    },
  },
];

const PHRASES = ["months upfront", "purchased outsourced doers"];
const needles = PHRASES.map(s => String(s).toLowerCase().trim()).filter(Boolean);

const tags = Array.isArray($json?.tags) ? $json.tags
  : Array.isArray($json?.data) ? $json.data
  : Array.isArray($json) ? $json
  : [];

const monthTags = tags.filter(t => {
  const name = String(t?.name || "").toLowerCase();
  return needles.every(p => name.includes(p));
});

return [{ json: { monthTags } }];

const tagMap = {};

// Build tagMap from monthTags.matches
const monthTagsRaw = $input.first().json.monthTags ?? {};
const matches = Array.isArray(monthTagsRaw?.matches)
  ? monthTagsRaw.matches
  : Array.isArray(monthTagsRaw)
    ? monthTagsRaw
    : [];

for (const t of matches) {
  if (t?.id != null && t?.name) tagMap[String(t.id)] = String(t.name);
}

// Type + Shift tag ids
const TAG_DMVA_FT = "14775";
const TAG_DMVA_PT = "14777";
const TAG_EC_FT   = "14779";
const TAG_EC_PT   = "14781";

const inputItems = $input.all() || [];
const out = [];

for (const it of inputItems) {
  const tagIdsRaw = Array.isArray(it.json.tag_ids) ? it.json.tag_ids : [];
  const tagIds = tagIdsRaw.map(id => String(id)); // normalize to strings
  const tagNames = tagIds.map(id => tagMap[id]).filter(Boolean);

  // Determine type + shift
  let type = "";
  let shift = "";

  const hasDMVA = tagIds.includes(TAG_DMVA_FT) || tagIds.includes(TAG_DMVA_PT);
  const hasEC   = tagIds.includes(TAG_EC_FT)   || tagIds.includes(TAG_EC_PT);

  if (hasDMVA) {
    type = "DMVA";
    if (tagIds.includes(TAG_DMVA_FT)) shift = "FT";
    else if (tagIds.includes(TAG_DMVA_PT)) shift = "PT";
  } else if (hasEC) {
    type = "EC";
    if (tagIds.includes(TAG_EC_FT)) shift = "FT";
    else if (tagIds.includes(TAG_EC_PT)) shift = "PT";
  }

  // Remove tag_ids and monthTags
  const { tag_ids, monthTags, ...rest } = it.json;

  const next = { ...rest };

  if (tagNames.length) next.tag_names = tagNames;
  if (type) next.type = type;
  if (shift) next.shift = shift;

  // drop empty objects
  if (Object.keys(next).length === 0) continue;

  out.push({ json: next });
}

return out;

const pickEmail = (arr) => {
  if (!Array.isArray(arr)) return "";

  const toLower = (e) =>
    String(e ?? "")
      .replace(/\u00A0/g, " ")
      .replace(/[\u200B-\u200D\uFEFF]/g, "")
      .trim()
      .toLowerCase();

  const email1 = arr.find(e => e?.field === "EMAIL1")?.email;
  if (email1) return toLower(email1);

  const email2 = arr.find(e => e?.field === "EMAIL2")?.email;
  if (email2) return toLower(email2);

  const fallback = arr[0]?.email;
  return fallback ? toLower(fallback) : "";
};

const pickCF = (arr, id) => {
  if (!Array.isArray(arr)) return "";
  const hit = arr.find(cf => String(cf?.id) === String(id));
  return String(hit?.content ?? "").trim();
};

const extractMonths = (tagNames) => {
  const tags = Array.isArray(tagNames) ? tagNames : [];
  for (const t of tags) {
    const s = String(t || "").toLowerCase();
    const m = s.match(/purchased\s+outsourced\s+doers\s+(.+?)\s+upfront/i);
    if (m && m[1]) {
      const between = m[1].trim(); // e.g. "5 Months"
      const m2 = between.match(/(\d+)\s*Months?/i);
      if (m2) return `${m2[1]} months`;
      return between;
    }
    // fallback: find just the first "N Months" anywhere
    const m3 = s.match(/(\d+)\s*Months?/i);
    if (m3) return `${m3[1]} months`;
  }
  return "";
};

