// Offboarded contacts array from "Get Offboarded Contacts"
const offboardedContacts = $('Get Offboarded Contacts').first().json.contacts ?? '';

// Build Set of offboarded IDs
const offboardedIds = new Set(
  (Array.isArray(offboardedContacts) ? offboardedContacts : [])
    .map(c => c?.id)
    .filter(id => id !== undefined && id !== null)
    .map(id => String(id))
);

// Collect all contacts from all data blocks, filter, dedupe by id
const contactsById = new Map();

for (const item of items) {
  const dataArr = Array.isArray(item?.data) ? item.data : [];
  for (const d of dataArr) {
    const contacts = Array.isArray(d?.contacts) ? d.contacts : [];
    for (const c of contacts) {
      const id = c?.id;
      if (id === undefined || id === null) continue;

      const idStr = String(id);

      // remove if offboarded
      if (offboardedIds.has(idStr)) continue;

      // keep and dedupe
      if (!contactsById.has(idStr)) contactsById.set(idStr, c);
    }
  }
}

return [
  {
    json: {
      contacts: Array.from(contactsById.values()),
