const baseUrl = "https://api.infusionsoft.com/crm/rest/v2";

const contactsById = new Map();

async function fetchContactsForTag(tagId) {
  let pageToken;

  do {
    const qs = { limit: 1000 };
    if (pageToken) qs.page_token = pageToken;

    const res = await this.helpers.httpRequest({
      method: "GET",
      url: `${baseUrl}/tags/${tagId}/contacts`,
      qs,
      headers: {
        Authorization: `Bearer ${token}`,
        Accept: "application/json",
      },
      json: true,
    });

    const contacts = Array.isArray(res?.contacts) ? res.contacts : [];
    for (const c of contacts) {
      if (c?.id !== undefined && c?.id !== null) {
        contactsById.set(String(c.id), c);
      }
    }

    pageToken = res?.next_page_token || undefined;
  } while (pageToken);
}

for (const tagId of tagIds) {
  await fetchContactsForTag.call(this, tagId);
}

return [
  {
    json: {
      contacts: Array.from(contactsById.values()).map((c) => ({ id: c.id })),
