function clean(s) {
  return String(s ?? "")
    .replace(/\u00A0/g, " ")
    .replace(/[\u200B-\u200D\uFEFF]/g, "")
    .trim();
}

function norm(s) {
  return clean(s);
}

function normEmail(s) {
  return clean(s).toLowerCase();
}

function truthyAnswer(v) {
  const s = norm(v);
  if (!s) return false;
  const low = s.toLowerCase();
  if (low === "none" || low === "none yet" || low === "n/a") return false;
  return true;
}

function findKeyLike(row, patterns) {
  const keys = Object.keys(row || {});
  const lowerKeys = keys.map(k => [k, String(k).toLowerCase()]);
  for (const p of patterns) {
    const hit = lowerKeys.find(([, lk]) => lk.includes(p));
    if (hit) return hit[0];
  }
  return null;
}

function findRevenueValue(row) {
  const revenueKey = findKeyLike(row, ["current monthly revenue", "monthly revenue", "revenue"]);
  return revenueKey ? row[revenueKey] : "";
}

function combineFields(row, fields) {
  const parts = fields.map(f => norm(row?.[f])).filter(truthyAnswer);

  const seen = new Set();
  const unique = [];
  for (const p of parts) {
    const key = p.toLowerCase();
    if (!seen.has(key)) {
      seen.add(key);
      unique.push(p);
    }
  }
  return unique.join(", ");
}

function normalizeMonthsSubscribed(s) {
  const raw = norm(s);
  if (!raw) return "";
  const m = raw.match(/(\d+)\s*months?/i);
  return m ? `${m[1]} months` : raw.toLowerCase();
}

function clampScore1to5(x) {
  const n = Number(String(x ?? "").trim());
  if (!Number.isFinite(n)) return 1;
  if (n < 1) return 1;
  if (n > 5) return 5;
  return n;
}

function revenueTierFromRevenueRaw(revenueRaw) {
  const tier = REVENUE_TO_LEAD_SCORE[norm(revenueRaw)];
  return tier || "Hustler";
}

function computePriority({ contractLength, applicationQualityScore, revenueRaw }) {
  const c = normalizeMonthsSubscribed(contractLength);
  if (!c) return "P12";

  if (c === "12 months") {
    const score = clampScore1to5(applicationQualityScore);
    return PRIORITY_MAP[`${c}|${score}`] || "P12";
  }

  const tier = revenueTierFromRevenueRaw(revenueRaw);
  return PRIORITY_MAP[`${c}|${tier}`] || "P12";
}

