const prevItems = $input.all() || [];
const prevByEmail = new Map();

for (const it of prevItems) {
  const row = it.json || {};
  const email = normEmail(row.email || row["Email"] || row["Doer Email"]);
  if (!email) continue;

  // keep first. change to overwrite if you prefer latest
  if (!prevByEmail.has(email)) prevByEmail.set(email, row);
