const baseItems = $items("Finalize Output") || [];

if (baseItems.length === 0) {
  return [{ json: { note: 'No items found from node "Finalize Output". Check node name.' } }];
}

// --------------------
// 3) LEFT JOIN
// --------------------
const out = [];

for (const it of baseItems) {
  const base = it.json || {};

  const baseEmail = normEmail(base.email);
  const baseFullName = norm(base.fullName);
  const baseId = norm(base.id);
  const founder_category = norm(base.founder_category);
  const founder_shift = norm(base.founder_shift);

  const matched = baseEmail ? (prevByEmail.get(baseEmail) || null) : null;

  const monthsSubscribedRaw = norm(base.monthsSubscribed);
  const contract_length = normalizeMonthsSubscribed(monthsSubscribedRaw);
  const founder_type = base.founder_type;

  const applicationQualityScore = clampScore1to5(base.score);

  // Revenue only exists on the previous node. If no match, revenueRaw is blank.
  const revenue_raw = matched ? norm(findRevenueValue(matched)) : "";

  let priority;
  if (founder_category === "Rematch") {
    priority = "P1";
  } else {
    priority = computePriority({
      contractLength: contract_length,
      applicationQualityScore,
      revenueRaw: revenue_raw,
    });
  }

  // lead_score stays 1..5 from Finalize Output "score"
  const lead_score = applicationQualityScore;

  out.push({
    json: {
      full_name: baseFullName,
      email: baseEmail,
      KeapId: baseId || null,
      MonthsSubscribed: monthsSubscribedRaw || null,
      contract_length,
      lead_score,
      priority,
      founder_category: founder_category || null,
      founder_type: founder_type || null,
      OnboardingDay: norm(base.onboarding) || null,
      founder_shift: founder_shift || null,

      // These come from the previous node only if matched, else blanks
      revenue_raw: revenue_raw || "",
      business_statement: matched ? norm(matched[BUSINESS_STATEMENT_FIELD]) : "",
      combined_industry_niche: matched ? combineFields(matched, INDUSTRY_FIELDS) : "",
      combined_tools_preferences: matched ? combineFields(matched, TOOL_PREF_FIELDS) : "",
      doing_blueprint_priorities: matched ? norm(matched[BLUEPRINT_PRIORITIES_FIELD]) : "",
    },
  });
}

return out;

function norm(v) {
  return (v === null || v === undefined) ? "" : String(v).trim();
