// Get Monday (start of day) for the current week in UTC, then format d MMM yyyy
function getUtcMondayFormatted() {
  const now = new Date();

  // UTC "today" at 00:00:00
  const utcTodayStart = new Date(Date.UTC(
    now.getUTCFullYear(),
    now.getUTCMonth(),
    now.getUTCDate(),
    0, 0, 0, 0
  ));

  // 0=Sun..6=Sat in UTC
  const dow = utcTodayStart.getUTCDay();

  // Monday-based week: Monday=0, Tuesday=1, ..., Sunday=6
  const diffToMonday = (dow + 6) % 7;

  const utcMondayStart = new Date(utcTodayStart.getTime() - diffToMonday * 24 * 60 * 60 * 1000);

  const day = String(utcMondayStart.getUTCDate()); // no leading 0
  const month = utcMondayStart.toLocaleString("en-GB", { month: "short", timeZone: "UTC" });
  const year = utcMondayStart.getUTCFullYear();

  return `${day} ${month} ${year}`;
}

const mondayFormatted = getUtcMondayFormatted();
