function clean(s) {
  return String(s ?? "")
    .replace(/\u00A0/g, " ")
    .replace(/[\u200B-\u200D\uFEFF]/g, "")
    .trim();
}

function normLower(s) {
  return clean(s).toLowerCase();
}

// Filter OUT internal emails containing these substrings
const BLOCKED_EMAIL_SUBSTRINGS = ["outsourceddoer", "doneverse"];

function hasBlockedEmail(emailAddresses) {
  if (!Array.isArray(emailAddresses) || emailAddresses.length === 0) return false;

  for (const e of emailAddresses) {
    const email = normLower(e?.email || e?.address || e?.value || "");
    if (!email) continue;

    if (BLOCKED_EMAIL_SUBSTRINGS.some(sub => email.includes(sub))) {
      return true;
    }
  }
  return false;
}

const pickCF = (customFields) => {
  if (!Array.isArray(customFields)) return [];
  return customFields
    .filter(cf => KEEP_CF_IDS.has(String(cf?.id)))
    .map(cf => ({
      id: cf.id,
      content: clean(cf?.content),
    }));
};

const out = [];

for (const c of contacts) {
  const customFields = Array.isArray(c?.custom_fields) ? c.custom_fields : [];

  const emailAddresses = Array.isArray(c?.email_addresses) ? c.email_addresses : [];

  // Keep the email filter. remove contacts with internal emails
  if (hasBlockedEmail(emailAddresses)) continue;

  out.push({
    json: {
      id: c.id ?? null,
      given_name: c.given_name ?? "",
      family_name: c.family_name ?? "",
      preferred_name: c.preferred_name ?? "",
      email_addresses: emailAddresses,
      tag_ids: Array.isArray(c?.tag_ids) ? c.tag_ids : [],
      custom_fields: pickCF(customFields),
      category: "Rematch"
    }
  });
}

return out;
